-- Import the operational records from "Farm Management  Data Records.xlsx".
-- The source workbook is intentionally not parsed at runtime. This migration stores
-- normalized, auditable records with deterministic ids/import keys so every environment
-- receives the same dataset exactly once.

INSERT INTO farms (id, farm_code, name, country, status, description, notes, created_at, updated_at)
VALUES
  ('xlsx-2026-farm-land-a', 'FARM-LAND-A', 'Farm Land A', 'Ghana', 'active', 'JBA Green Gold orchard land A', 'Profile completed from the farm management workbook.', now(), now()),
  ('xlsx-2026-farm-land-b', 'FARM-LAND-B', 'Farm Land B', 'Ghana', 'active', 'JBA Green Gold orchard land B', 'Profile completed from the farm management workbook.', now(), now())
ON CONFLICT (farm_code) DO UPDATE SET
  name = EXCLUDED.name,
  country = COALESCE(farms.country, EXCLUDED.country),
  status = 'active',
  description = COALESCE(farms.description, EXCLUDED.description),
  notes = COALESCE(farms.notes, EXCLUDED.notes),
  updated_at = now();

WITH block_seed (
  seed_id, farm_code, block_code, block_name, description, workbook_stage,
  shoot_maturity, variety, fruit_fly_pressure, disease_rating, early_harvest
) AS (
  VALUES
  ('xlsx-2026-block-a1', 'FARM-LAND-A', 'A1', 'Block A1', 'Farm close to the road; it borders the cashew farm', 'Yes', 1, 'Kent', 'Medium', 'Medium', true),
