  ('xlsx-2026-block-a3', 'FARM-LAND-A', 'A3', 'Block A3', 'Togbui''s farming area', 'Mid', 0.7, 'Kent', 'Medium', 'Medium', false),
  ('xlsx-2026-block-a4', 'FARM-LAND-A', 'A4', 'Block A4', 'Land purchased from Amoateng', 'New', 0, 'Keitt', 'Medium', 'Medium', false),
  ('xlsx-2026-block-a5', 'FARM-LAND-A', 'A5', 'Block A5', 'New', 'New', 0, 'Keitt', 'NA', 'NA', false),
  ('xlsx-2026-block-b1', 'FARM-LAND-B', 'B1', 'Block B1', 'Osofo''s farms', 'Mid', 0.7, 'Keitt', 'Medium', 'Medium', false),
  ('xlsx-2026-block-b2', 'FARM-LAND-B', 'B2', 'Block B2', 'Ananes Farms', 'Mid', 0.5, 'Keitt', 'Medium', 'Medium', false),
  ('xlsx-2026-block-b3', 'FARM-LAND-B', 'B3', 'Block B3', 'Kwaku Boakye''s farm', 'Mid', 0.6, 'Black Pearl', 'Medium', 'Medium', false),
  ('xlsx-2026-block-b4', 'FARM-LAND-B', 'B4', 'Block B4', 'Where the oil palm is', 'New', 0, 'Black Pearl', 'Medium', 'Medium', false),
