INSERT INTO farm_blocks (
  id, farm_id, block_code, name, soil_notes, variety, status, programme_code,
  source, early_harvest, shoot_maturity, forecast_yield_kg,
  fruit_fly_pressure, disease_rating, created_at, updated_at
)
SELECT
  seed.seed_id,
  farm.id,
  seed.block_code,
  seed.block_name,
  seed.description || ' | Workbook early-block classification: ' || seed.workbook_stage,
  seed.variety,
  'active',
  'JBA-EARLY-HARVEST-2026-27',
  'Farm Management  Data Records.xlsx',
  seed.early_harvest,
  seed.shoot_maturity,
  0,
  seed.fruit_fly_pressure,
  seed.disease_rating,
  now(),
  now()
FROM block_seed seed
JOIN farms farm ON farm.farm_code = seed.farm_code
ON CONFLICT (farm_id, block_code) DO UPDATE SET
  name = EXCLUDED.name,
  soil_notes = EXCLUDED.soil_notes,
  variety = COALESCE(farm_blocks.variety, EXCLUDED.variety),
  status = 'active',
  programme_code = EXCLUDED.programme_code,
  source = EXCLUDED.source,
  early_harvest = EXCLUDED.early_harvest,
  shoot_maturity = EXCLUDED.shoot_maturity,
  fruit_fly_pressure = EXCLUDED.fruit_fly_pressure,
  disease_rating = EXCLUDED.disease_rating,
  updated_at = now();

