INSERT INTO entity_records (
  id, entity_name, organization_id, owner_user_id, data,
  created_by, updated_by, created_at, updated_at
)
SELECT
  record->>'id',
  record->>'entityName',
  NULL,
  NULL,
  record->'data',
  NULL,
  NULL,
  now(),
  now()
FROM seed_record
ON CONFLICT (id) DO UPDATE SET
  entity_name = EXCLUDED.entity_name,
  data = EXCLUDED.data,
  updated_at = now();

-- Attach canonical farm/block ids after resolving any pre-existing rows that won the
-- unique farm-code or farm/block-code constraints.
UPDATE entity_records record
SET data = record.data || jsonb_build_object('farm_id', farm.id),
    updated_at = now()
FROM farms farm
WHERE record.data->>'source_workbook' = 'Farm Management  Data Records.xlsx'
  AND record.data->>'farm_name' = farm.name;

UPDATE entity_records record
SET data = record.data || jsonb_build_object('farm_id', farm.id, 'block_id', block.id, 'block_name', block.name),
    updated_at = now()
FROM farm_blocks block
JOIN farms farm ON farm.id = block.farm_id
WHERE record.data->>'source_workbook' = 'Farm Management  Data Records.xlsx'
  AND record.data->>'block_code' = block.block_code
  AND record.data->>'farm_name' = farm.name;

